#include <iostream>
using namespace std;
class Student {
protected:
    int roll_no;
    char name[30];
public:
    void getStudent() {
        cout << "Enter Roll No and Name: ";
        cin >> roll_no >> name;
    }
};
class Marks : public Student {
    float m1, m2, total;
public:
    void getMarks() {
        getStudent();
        cout << "Enter Marks in 2 subjects: ";
        cin >> m1 >> m2;
        total = m1 + m2;
    }
    void display() {
        cout << "\nRoll No: " << roll_no << ", Name: " << name << endl;
        cout << "Total Marks: " << total << endl;
    }
};
int main() {
    Marks student1;
    student1.getMarks();
    student1.display();
    return 0;
}

