#include <iostream>
using namespace std;
class Person {
protected:
    char name[30];
public:
    void getName() { cout << "Enter Name: "; cin >> name; }
};
class Employee : public Person {
protected:
    int emp_id;
public:
    void getEmp() { getName(); cout << "Enter ID: "; cin >> emp_id; }
};
class Manager : public Employee {
    float salary;
public:
    void getManager() { getEmp(); cout << "Enter Salary: "; cin >> salary; }
    void show() {
        cout << "\n--- Details ---\nName: " << name << "\nID: " << emp_id << "\nSalary: " << salary << endl;
    }
};
int main() {
    Manager m; m.getManager(); m.show();
    return 0;
}

